<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>City Day-Night Cycle</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body, html { width: 100%; height: 100%; overflow: hidden; background: #000; }
    canvas { display: block; width: 100vw; height: 100vh; }
  </style>
</head>
<body>
<canvas id="skyline"></canvas>
<script>
  const canvas = document.getElementById('skyline');
  const ctx = canvas.getContext('2d');

  let width, height;
  let stars = [];
  let buildings = [];

  const CYCLE_DURATION = 10000; // 10 seconds

  // Sky keyframes: time (0-1), top color [r,g,b], bottom color [r,g,b]
  const skyPalette = [
    { t: 0.00, top: [20, 24, 70],    bot: [240, 130, 80] },  // Dawn
    { t: 0.15, top: [70, 150, 240],  bot: [180, 220, 255] }, // Morning
    { t: 0.35, top: [40, 130, 230],  bot: [160, 215, 250] }, // Noon
    { t: 0.50, top: [65, 30, 95],    bot: [245, 110, 60] },  // Sunset
    { t: 0.65, top: [15, 15, 45],    bot: [45, 25, 60] },    // Dusk
    { t: 0.75, top: [3, 4, 15],      bot: [10, 12, 30] },    // Midnight
    { t: 0.90, top: [10, 12, 35],    bot: [25, 20, 45] },    // Pre-dawn
    { t: 1.00, top: [20, 24, 70],    bot: [240, 130, 80] }   // Dawn loop
  ];

  function resize() {
    width = canvas.width = window.innerWidth;
    height = canvas.height = window.innerHeight;
    initScene();
  }

  function initScene() {
    // Generate stars
    stars = [];
    const starCount = Math.floor((width * height) / 3500);
    for (let i = 0; i < starCount; i++) {
      stars.push({
        x: Math.random() * width,
        y: Math.random() * height * 0.65,
        radius: Math.random() * 1.5 + 0.5,
        baseAlpha: Math.random() * 0.7 + 0.3,
        twinkleSpeed: Math.random() * 3 + 2
      });
    }

    // Generate cityscape (two layers for depth)
    buildings = [];
    const layers = [
      { count: Math.ceil(width / 45) + 2, minW: 35, maxW: 70, minH: 0.25, maxH: 0.55, color: '#090a14' },
      { count: Math.ceil(width / 60) + 2, minW: 50, maxW: 95, minH: 0.15, maxH: 0.42, color: '#05050b' }
    ];

    layers.forEach((layer, layerIdx) => {
      let x = -20;
      while (x < width + 50) {
        const w = layer.minW + Math.random() * (layer.maxW - layer.minW);
        const h = height * (layer.minH + Math.random() * (layer.maxH - layer.minH));
        const y = height - h;

        // Windows
        const windows = [];
        const cols = Math.floor((w - 12) / 9);
        const rows = Math.floor((h - 20) / 14);
        const xOffset = (w - (cols * 9 - 3)) / 2;

        for (let r = 0; r < rows; r++) {
          for (let c = 0; c < cols; c++) {
            if (Math.random() > 0.25) {
              windows.push({
                x: x + xOffset + c * 9,
                y: y + 12 + r * 14,
                w: 5,
                h: 7,
                hue: Math.random() > 0.2 ? '255, 220, 120' : '180, 230, 255',
                litThreshold: Math.random() * 0.7 // stagger lights turning on
              });
            }
          }
        }

        // Roof features
        const roofType = Math.random();
        let antenna = null;
        if (roofType > 0.6) {
          antenna = {
            x: x + w * (0.3 + Math.random() * 0.4),
            h: 15 + Math.random() * 30
          };
        }

        buildings.push({
          x, y, w, h,
          layer: layerIdx,
          color: layer.color,
          windows,
          antenna
        });

        x += w - (layerIdx === 0 ? 8 : 12);
      }
    });
  }

  function lerp(a, b, t) {
    return a + (b - a) * t;
  }

  function getSkyColors(progress) {
    let i = 0;
    while (i < skyPalette.length - 1 && skyPalette[i + 1].t < progress) {
      i++;
    }
    const k1 = skyPalette[i];
    const k2 = skyPalette[i + 1];
    const factor = (progress - k1.t) / (k2.t - k1.t);

    const top = [
      Math.round(lerp(k1.top[0], k2.top[0], factor)),
      Math.round(lerp(k1.top[1], k2.top[1], factor)),
      Math.round(lerp(k1.top[2], k2.top[2], factor))
    ];
    const bot = [
      Math.round(lerp(k1.bot[0], k2.bot[0], factor)),
      Math.round(lerp(k1.bot[1], k2.bot[1], factor)),
      Math.round(lerp(k1.bot[2], k2.bot[2], factor))
    ];

    return { top: `rgb(${top})`, bot: `rgb(${bot})` };
  }

  function render(time) {
    const progress = (time % CYCLE_DURATION) / CYCLE_DURATION;

    // Night factor: 0 at noon (0.25), 1 at midnight (0.75)
    const nightFactor = Math.sin((progress - 0.25) * Math.PI * 2) * 0.5 + 0.5;

    // 1. Sky Background
    const sky = getSkyColors(progress);
    const grad = ctx.createLinearGradient(0, 0, 0, height);
    grad.addColorStop(0, sky.top);
    grad.addColorStop(1, sky.bot);
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, width, height);

    // 2. Stars (visible at night)
    if (nightFactor > 0.05) {
      stars.forEach(star => {
        const twinkle = 0.7 + 0.3 * Math.sin(time * 0.003 * star.twinkleSpeed + star.x);
        const alpha = star.baseAlpha * Math.min(1, (nightFactor - 0.05) / 0.4) * twinkle;
        ctx.fillStyle = `rgba(255, 255, 255, ${alpha})`;
        ctx.beginPath();
        ctx.arc(star.x, star.y, star.radius, 0, Math.PI * 2);
        ctx.fill();
      });
    }

    // 3. Sun (Day: progress 0.0 -> 0.5)
    if (progress >= 0.0 && progress <= 0.5) {
      const sunP = progress / 0.5;
      const sunX = sunP * (width + 120) - 60;
      const sunY = height * 0.78 - Math.sin(sunP * Math.PI) * (height * 0.65);

      // Glow
      const glow = ctx.createRadialGradient(sunX, sunY, 15, sunX, sunY, 90);
      glow.addColorStop(0, 'rgba(255, 230, 160, 0.9)');
      glow.addColorStop(0.3, 'rgba(255, 180, 80, 0.4)');
      glow.addColorStop(1, 'rgba(255, 120, 0, 0)');
      ctx.fillStyle = glow;
      ctx.beginPath();
      ctx.arc(sunX, sunY, 90, 0, Math.PI * 2);
      ctx.fill();

      // Sun Core
      ctx.fillStyle = '#fff9e6';
      ctx.beginPath();
      ctx.arc(sunX, sunY, 26, 0, Math.PI * 2);
      ctx.fill();
    }

    // 4. Moon (Night: progress 0.5 -> 1.0)
    if (progress >= 0.5 && progress <= 1.0) {
      const moonP = (progress - 0.5) / 0.5;
      const moonX = moonP * (width + 120) - 60;
      const moonY = height * 0.78 - Math.sin(moonP * Math.PI) * (height * 0.65);

      // Glow
      const glow = ctx.createRadialGradient(moonX, moonY, 12, moonX, moonY, 65);
      glow.addColorStop(0, 'rgba(230, 240, 255, 0.6)');
      glow.addColorStop(0.4, 'rgba(180, 205, 255, 0.2)');
      glow.addColorStop(1, 'rgba(150, 180, 255, 0)');
      ctx.fillStyle = glow;
      ctx.beginPath();
      ctx.arc(moonX, moonY, 65, 0, Math.PI * 2);
      ctx.fill();

      // Moon Body
      ctx.fillStyle = '#f4f7fc';
      ctx.beginPath();
      ctx.arc(moonX, moonY, 20, 0, Math.PI * 2);
      ctx.fill();

      // Moon Crescent Shadow
      ctx.fillStyle = sky.top;
      ctx.beginPath();
      ctx.arc(moonX + 7, moonY - 4, 17, 0, Math.PI * 2);
      ctx.fill();
    }

    // 5. City Skyline
    buildings.forEach(b => {
      // Silhouette
      ctx.fillStyle = b.color;
      ctx.fillRect(b.x, b.y, b.w, b.h);

      // Antenna
      if (b.antenna) {
        ctx.strokeStyle = b.color;
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.moveTo(b.antenna.x, b.y);
        ctx.lineTo(b.antenna.x, b.y - b.antenna.h);
        ctx.stroke();

        // Beacon light blinking at night
        if (nightFactor > 0.3) {
          const beaconBlink = Math.sin(time * 0.008) > 0.3;
          if (beaconBlink) {
            ctx.fillStyle = 'rgba(255, 50, 50, 0.9)';
            ctx.beginPath();
            ctx.arc(b.antenna.x, b.y - b.antenna.h, 2, 0, Math.PI * 2);
            ctx.fill();
          }
        }
      }

      // Windows
      b.windows.forEach(w => {
        if (nightFactor > w.litThreshold) {
          const windowIntensity = Math.min(1, (nightFactor - w.litThreshold) * 3);
          const alpha = windowIntensity * (b.layer === 0 ? 0.65 : 0.9);
          ctx.fillStyle = `rgba(${w.hue}, ${alpha})`;
          ctx.fillRect(w.x, w.y, w.w, w.h);
        } else {
          // Off window reflection during day
          ctx.fillStyle = 'rgba(255, 255, 255, 0.03)';
          ctx.fillRect(w.x, w.y, w.w, w.h);
        }
      });
    });

    requestAnimationFrame(render);
  }

  window.addEventListener('resize', resize);
  resize();
  requestAnimationFrame(render);
</script>
</body>
</html>
```

The animation derives a normalized cycle progress from timestamps using modulo ten seconds, interpolating gradient sky palettes, tracing sinusoidal flight paths for the sun and moon, and fading in procedural stars and building window lights in sync with an undulating night-factor metric.
